 46	    @MainActor
 47	    @discardableResult
 48	    static func getOrRegister(_ nsApp: NSRunningApplication) async throws -> MacApp? {
 49	        // Don't perceive any of the lock screen windows as real windows
 50	        // Otherwise, false positive ax notifications might trigger that lead to gcWindows
 51	        if nsApp.bundleIdentifier == lockScreenAppBundleId { return nil }
 52	        let pid = nsApp.processIdentifier
 53	        // AX requests crash if you send them to yourself
 54	        if pid == myPid { return nil }
 55	
 56	        if let existing = allAppsMap[pid] { return existing }
 57	        try checkCancellation()
 58	        if let wip = wipPids[pid] {
 59	            try await wip.await()
 60	            return allAppsMap[pid]
 61	        }
 62	        let wip = AwaitableOneTimeBroadcastLatch()
 63	        wipPids[pid] = wip
 64	
 65	        let thread = Thread {
 66	            $axTaskLocalAppThreadToken.withValue(AxAppThreadToken(pid: pid, idForDebug: nsApp.idForDebug)) {
 67	                let axApp = AXUIElementCreateApplication(nsApp.processIdentifier)
 68	                let handlers: HandlerToNotifKeyMapping = unsafe [
 69	                    (refreshObs, [kAXWindowCreatedNotification, kAXFocusedWindowChangedNotification]),
 70	                ]
 71	                let job = RunLoopJob(.cancellable)
 72	                let subscriptions = (try? unsafe AxSubscription.bulkSubscribe(nsApp, axApp, job, handlers)) ?? []
 73	                let isGood = !subscriptions.isEmpty
 74	                let app = isGood ? MacApp(nsApp, axApp, subscriptions, Thread.current) : nil
 75	
 76	                let appAxSubscriptionsThreadGuarded = app?.appAxSubscriptions
 77	                let windowsThreadGuarded = app?.windows
 78	                let axAppThreadGuarded = app?.axApp
 79	
 80	                Task.startUnstructured { @MainActor in
 81	                    allAppsMap[pid] = app
 82	                    wipPids[pid] = nil
 83	                    await wip.signalToAll()
 84	                }
 85	                if isGood {
 86	                    CFRunLoopRun()
 87	
 88	                    // Destroy AX objects in reverse order of their creation
 89	                    appAxSubscriptionsThreadGuarded?.destroy()
 90	                    windowsThreadGuarded?.destroy()
 91	                    axAppThreadGuarded?.destroy()
 92	                }
 93	            }
 94	        }
 95	        thread.name = "AxAppThread \(nsApp.idForDebug)"
 96	        thread.start()
 97	
 98	        try await wip.await()
 99	        return allAppsMap[pid]
100	    }
