130	    @MainActor func nativeFocus(_ windowId: UInt32) {
131	        if serverArgs.isReadOnly { return }
132	        MacApp.focusJob?.cancel()
133	        // Performance optimization. If possible avoid doing AX requests
134	        // (important for apps which are slow at responding even such basic AX requests. E.g. Godot)
135	        // Beware of the macOS bug: https://github.com/nikitabobko/AeroSpace/issues/101
136	        if (!NSScreen.screensHaveSeparateSpaces || monitors.count == 1) &&
137	            (lastNativeFocusedWindowId == windowId || windowsCount == 1)
138	        {
139	            nsApp.activate(options: .activateIgnoringOtherApps)
140	        } else {
141	            MacApp.focusJob = withWindowAsync(windowId, .cancellable) { [nsApp] window, job in
142	                // Raise firstly to make sure that by the time we activate the app, the window would be already on top
143	                window.set(Ax.isMainAttr, true)
144	                AXUIElementPerformAction(window, kAXRaiseAction as CFString)
145	                nsApp.activate(options: .activateIgnoringOtherApps)
146	            }
147	        }
148	    }
