259	    @MainActor
260	    static func refreshAllAndGetAliveWindowIds(frontmostAppBundleId: String?) async throws -> [MacApp: [UInt32]] {
261	        for (_, app) in MacApp.allAppsMap { // gc dead apps
262	            try checkCancellation()
263	            if app.nsApp.isTerminated {
264	                await app.destroy()
265	            }
266	        }
267	        return try await withThrowingTaskGroup(of: (pid_t, [UInt32]).self, returning: [MacApp: [UInt32]].self) { group in
268	            func refreshTheApp(_ nsApp: NSRunningApplication) {
269	                group.addTask { @Sendable @MainActor in
270	                    guard let app = try await MacApp.getOrRegister(nsApp) else { return (nsApp.processIdentifier, []) }
271	                    return (nsApp.processIdentifier, try await app.refreshAndGetAliveWindowIds(frontmostAppBundleId: frontmostAppBundleId))
272	                }
273	            }
274	            // Register new apps
275	            for nsApp in NSWorkspace.shared.runningApplications {
276	                try checkCancellation()
277	                if nsApp.activationPolicy == .regular {
278	                    refreshTheApp(nsApp)
279	                }
280	            }
281	            for (_, app) in MacApp.allAppsMap {
282	                try checkCancellation()
283	                // "About this Mac" window, TouchID, and a lot of other utility windows
284	                // We don't monitor them actively as we do for regular apps, but if a window of one of those utility
285	                // apps got focused it will end up in allAppsMap
286	                if app.nsApp.activationPolicy != .regular {
287	                    refreshTheApp(app.nsApp)
288	                }
289	            }
290	            var result: [MacApp: [UInt32]] = [:]
291	            for try await (pid, windowIds) in group {
292	                if let app = MacApp.allAppsMap[pid] {
293	                    result[app] = windowIds
294	                }
295	            }
296	            return result
297	        }
298	    }
