300	    private func refreshAndGetAliveWindowIds(frontmostAppBundleId: String?) async throws -> [UInt32] {
301	        if nsApp.isTerminated {
302	            await destroy()
303	            return []
304	        }
305	        guard let thread else { return [] }
306	        let (alive, dead) = try await thread.runInLoop(.cancellable) { [nsApp, windows, axApp] (job) -> ([UInt32], [UInt32]) in
307	            var alive: [UInt32: AxWindow] = windows.threadGuarded
308	            var dead = [UInt32: AxWindow]()
309	            // Second line of defence against lock screen. See the first line of defence: closedWindowsCache
310	            // Second and third lines of defence are technically needed only to avoid potential flickering
311	            if frontmostAppBundleId != lockScreenAppBundleId {
312	                (alive, dead) = try alive.partition {
313	                    try job.checkCancellation()
314	                    return $0.value.ax.containingWindowId() != nil
315	                }
316	            }
317	
318	            for (id, window) in axApp.threadGuarded.get(Ax.windowsAttr) ?? [] {
319	                try job.checkCancellation()
320	                try alive.getOrRegisterAxWindow(windowId: id, window, nsApp, job)
321	            }
322	
323	            windows.threadGuarded = alive
324	            return (Array(alive.keys), Array(dead.keys))
325	        }
326	        windowsCount = alive.count
327	        for windowId in dead {
328	            setFrameJobs.removeValue(forKey: windowId)?.cancel()
329	        }
330	        return alive
331	    }
