333	    private func destroy() async {
334	        _ = await Task.startUnstructured { @MainActor [pid] in _ = MacApp.allAppsMap.removeValue(forKey: pid) }.result
335	        for (_, job) in setFrameJobs {
336	            job.cancel()
337	        }
338	        setFrameJobs = [:]
339	        thread?.runInLoopAsync(job: RunLoopJob(.nonCancellable)) { job in CFRunLoopStop(CFRunLoopGetCurrent()) }
340	        thread = nil // Disallow all future job submissions
341	    }
