362	private final class AxWindow {
363	    let windowId: UInt32
364	    let ax: AXUIElement
365	    // periphery:ignore
366	    private let axSubscriptions: [AxSubscription] // keep subscriptions in memory
367	
368	    private init(windowId: UInt32, _ ax: AXUIElement, _ axSubscriptions: [AxSubscription]) {
369	        self.windowId = windowId
370	        self.ax = ax
371	        assert(!axSubscriptions.isEmpty)
372	        self.axSubscriptions = axSubscriptions
373	    }
374	
375	    static func new(windowId: UInt32, _ ax: AXUIElement, _ nsApp: NSRunningApplication, _ job: RunLoopJob) throws -> AxWindow? {
376	        let handlers: HandlerToNotifKeyMapping = unsafe [
377	            (refreshObs, [kAXUIElementDestroyedNotification, kAXWindowDeminiaturizedNotification, kAXWindowMiniaturizedNotification]),
378	            (movedObs, [kAXMovedNotification]),
379	            (resizedObs, [kAXResizedNotification]),
380	        ]
381	        let subscriptions = try unsafe AxSubscription.bulkSubscribe(nsApp, ax, job, handlers)
382	        return !subscriptions.isEmpty ? AxWindow(windowId: windowId, ax, subscriptions) : nil
383	    }
384	}
