386	extension [UInt32: AxWindow] {
387	    @discardableResult
388	    fileprivate mutating func getOrRegisterAxWindow(windowId id: UInt32, _ axWindow: AXUIElement, _ nsApp: NSRunningApplication, _ job: RunLoopJob) throws -> AxWindow? {
389	        if let existing = self[id] { return existing }
390	        // Delay new window detection if mouse is down
391	        // It helps with apps that allow dragging their tabs out to create new windows
392	        // https://github.com/nikitabobko/AeroSpace/issues/1001
393	        if isLeftMouseButtonDown { return nil }
394	
395	        if let window = try AxWindow.new(windowId: id, axWindow, nsApp, job) {
396	            self[id] = window
397	            return window
398	        } else {
399	            return nil
400	        }
401	    }
402	}
