157	@MainActor
158	private func layoutWorkspaces() async throws {
159	    if !TrayMenuModel.shared.isEnabled {
160	        for workspace in Workspace.all {
161	            workspace.allLeafWindowsRecursive.forEach { ($0 as! MacWindow).unhideFromCorner() } // todo as!
162	            try await workspace.layoutWorkspace() // Unhide tiling windows from corner
163	        }
164	        return
165	    }
166	    let monitors = monitors
167	    var monitorToOptimalHideCorner: [CGPoint: OptimalHideCorner] = [:]
168	    for monitor in monitors {
169	        let xOff = monitor.width * 0.1
170	        let yOff = monitor.height * 0.1
171	        // brc = bottomRightCorner
172	        let brc1 = monitor.rect.bottomRightCorner + CGPoint(x: 2, y: -yOff)
173	        let brc2 = monitor.rect.bottomRightCorner + CGPoint(x: -xOff, y: 2)
174	        let brc3 = monitor.rect.bottomRightCorner + CGPoint(x: 2, y: 2)
175	
176	        // blc = bottomLeftCorner
177	        let blc1 = monitor.rect.bottomLeftCorner + CGPoint(x: -2, y: -yOff)
178	        let blc2 = monitor.rect.bottomLeftCorner + CGPoint(x: xOff, y: 2)
179	        let blc3 = monitor.rect.bottomLeftCorner + CGPoint(x: -2, y: 2)
180	
181	        func contains(_ monitor: Monitor, _ point: CGPoint) -> Int { monitor.rect.contains(point) ? 1 : 0 }
182	        let important = 10
183	
184	        let corner: OptimalHideCorner =
185	            monitors.sumOfInt { contains($0, blc1) + contains($0, blc2) + important * contains($0, blc3) } <
186	            monitors.sumOfInt { contains($0, brc1) + contains($0, brc2) + important * contains($0, brc3) }
187	            ? .bottomLeftCorner
188	            : .bottomRightCorner
189	        monitorToOptimalHideCorner[monitor.rect.topLeftCorner] = corner
190	    }
191	
192	    // to reduce flicker, first unhide visible workspaces, then hide invisible ones
193	    for monitor in monitors {
194	        let workspace = monitor.activeWorkspace
195	        workspace.allLeafWindowsRecursive.forEach { ($0 as! MacWindow).unhideFromCorner() } // todo as!
196	        try await workspace.layoutWorkspace()
197	    }
198	    for workspace in Workspace.all where !workspace.isVisible {
199	        let corner = monitorToOptimalHideCorner[workspace.workspaceMonitor.rect.topLeftCorner] ?? .bottomRightCorner
200	        for window in workspace.allLeafWindowsRecursive {
201	            try await (window as! MacWindow).hideInCorner(corner) // todo as!
202	        }
203	    }
204	}
