23	@MainActor
24	private func _normalizeLayoutReason(workspace: Workspace, windows: [Window]) async throws {
25	    for window in windows {
26	        let isMacosFullscreen = try await window.isMacosFullscreen(.cancellable)
27	        let isMacosMinimized = try await (!isMacosFullscreen).andAsync { @MainActor @Sendable in try await window.isMacosMinimized(.cancellable) }
28	        let isMacosWindowOfHiddenApp = !isMacosFullscreen && !isMacosMinimized &&
29	            !config.automaticallyUnhideMacosHiddenApps && window.macAppUnsafe.nsApp.isHidden
30	        switch window.layoutReason {
31	            case .standard:
32	                guard let parent = window.parent else { continue }
33	                switch true {
34	                    case isMacosFullscreen:
35	                        window.layoutReason = .macos(prevParentKind: parent.kind)
36	                        window.bind(to: workspace.macOsNativeFullscreenWindowsContainer, adaptiveWeight: WEIGHT_DOESNT_MATTER, index: INDEX_BIND_LAST)
37	                    case isMacosMinimized:
38	                        window.layoutReason = .macos(prevParentKind: parent.kind)
39	                        window.bind(to: macosMinimizedWindowsContainer, adaptiveWeight: 1, index: INDEX_BIND_LAST)
40	                    case isMacosWindowOfHiddenApp:
41	                        window.layoutReason = .macos(prevParentKind: parent.kind)
42	                        window.bind(to: workspace.macOsNativeHiddenAppsWindowsContainer, adaptiveWeight: WEIGHT_DOESNT_MATTER, index: INDEX_BIND_LAST)
43	                    default: break
44	                }
45	            case .macos(let prevParentKind):
46	                if !isMacosFullscreen && !isMacosMinimized && !isMacosWindowOfHiddenApp {
47	                    try await exitMacOsNativeUnconventionalState(window: window, prevParentKind: prevParentKind, workspace: workspace, .cancellable)
48	                }
49	        }
50	    }
51	}
