53	@MainActor
54	func exitMacOsNativeUnconventionalState(
55	    window: Window,
56	    prevParentKind: NonLeafTreeNodeKind,
57	    workspace: Workspace,
58	    _ cm: CancellationMode,
59	) async throws {
60	    window.layoutReason = .standard
61	    switch prevParentKind {
62	        case .floatingWindowsContainer:
63	            window.bindAsFloatingWindow(to: workspace)
64	        case .workspace:
65	            break // Not possible
66	        case .tilingContainer:
67	            try await window.relayoutWindow(on: workspace, cm, forceTile: true)
68	        case .macosPopupWindowsContainer: // Since the window was minimized/fullscreened it was mistakenly detected as popup. Relayout the window
69	            try await window.relayoutWindow(on: workspace, cm)
70	        case .macosMinimizedWindowsContainer, .macosFullscreenWindowsContainer, .macosHiddenAppsWindowsContainer: // wtf case, should never be possible. But If encounter it, let's just re-layout window
71	            try await window.relayoutWindow(on: workspace, cm)
72	    }
73	}
