 8	func getWindowLevel(for windowId: UInt32) -> MacOsWindowLevel? {
 9	    if let existing = cache[windowId] { return existing }
10	
11	    var result: [UInt32: MacOsWindowLevel] = [:]
12	    let options = CGWindowListOption(arrayLiteral: .excludeDesktopElements, .optionOnScreenOnly)
13	    guard let cfArray = CGWindowListCopyWindowInfo(options, CGWindowID(0)) as? [CFDictionary] else { return nil }
14	    for elem in cfArray {
15	        let dict = elem as NSDictionary
16	
17	        guard let _windowLayer = dict[kCGWindowLayer] else { continue }
18	        let windowLayer = ((_windowLayer as! CFNumber) as NSNumber).intValue
19	
20	        guard let _windowId = dict[kCGWindowNumber] else { continue }
21	        let windowId = ((_windowId as! CFNumber) as NSNumber).uint32Value
22	
23	        result[windowId] = .new(windowLevel: windowLayer)
24	    }
25	    cache = result
26	    return result[windowId]
27	}
