 31	    @MainActor
 32	    private func capture(_ container: TilingContainer) async -> SnapshotNode {
 33	        let total = container.children.sumOfDouble { Double($0.getWeight(container.orientation)) }
 34	        var children: [SnapshotNode] = []
 35	        for child in container.children {
 36	            let weight = total > 0 ? Double(child.getWeight(container.orientation)) / total : 0
 37	            switch child.nodeCases {
 38	                case .window(let window):
 39	                    let title = (try? await window.getTitle(.nonCancellable)) ?? ""
 40	                    children.append(.window(window, title: title, weight: weight))
 41	                case .tilingContainer(let nested):
 42	                    var node = await capture(nested)
