 69	        var titles: [UInt32: String] = [:]
 70	        for window in pool {
 71	            titles[window.windowId] = (try? await window.getTitle(.nonCancellable)) ?? ""
 72	        }
 73	
 74	        let root = workspace.rootTilingContainer
 75	        let oldChildren = root.children
 76	        root.changeOrientation(snapshot.root.parsedOrientation)
 77	        root.layout = snapshot.root.parsedLayout
 78	
 79	        var used: Set<UInt32> = []
 80	        build(snapshot.root, into: root, pool: pool, titles: titles, used: &used)
 81	
 82	        // Windows that were already here but aren't part of the snapshot are appended at the end
 83	        for child in oldChildren {
 84	            for window in child.allLeafWindowsRecursive where !used.contains(window.windowId) {
 85	                window.bind(to: root, adaptiveWeight: WEIGHT_AUTO, index: INDEX_BIND_LAST)
 86	            }
 87	        }
 88	
 89	        let wanted = countWindows(snapshot.root)
 90	        let msg = "Restored \(used.count) of \(wanted) window(s) of '\(url.deletingPathExtension().lastPathComponent)' on workspace '\(workspace.name)'"
 91	        return used.count == wanted ? .succ(io.out(msg)) : .succ(io.err(msg))
 92	    }
