 94	    @MainActor
 95	    private func build(
 96	        _ node: SnapshotNode,
 97	        into parent: TilingContainer,
 98	        pool: [Window],
 99	        titles: [UInt32: String],
100	        used: inout Set<UInt32>,
101	    ) {
102	        guard let snapshotChildren = node.children else { return }
103	        var bound: [(SnapshotNode, TreeNode)] = []
104	        for child in snapshotChildren {
105	            switch child.kind {
106	                case .window:
107	                    guard let window = match(child, pool: pool, titles: titles, used: used) else { continue }
108	                    used.insert(window.windowId)
109	                    window.bind(to: parent, adaptiveWeight: WEIGHT_AUTO, index: INDEX_BIND_LAST)
110	                    bound.append((child, window))
111	                case .container:
112	                    let container = TilingContainer(
113	                        parent: parent,
114	                        adaptiveWeight: WEIGHT_AUTO,
115	                        child.parsedOrientation,
116	                        child.parsedLayout,
117	                        index: INDEX_BIND_LAST,
118	                    )
119	                    bound.append((child, container))
120	            }
121	        }
122	        // Weights are stored as fractions, so they must be applied top down, once the parent's own
123	        // weight is already final
124	        if parent.layout == .tiles {
125	            let total = Double(parent.getWeight(parent.orientation))
126	            let sum = bound.sumOfDouble { $0.0.weight }
127	            if total > 0 && sum > 0 {
128	                for (snapshotChild, treeChild) in bound {
129	                    treeChild.setWeight(parent.orientation, CGFloat(snapshotChild.weight / sum * total))
130	                }
131	            }
132	        }
133	        for (snapshotChild, treeChild) in bound {
134	            if let container = treeChild as? TilingContainer {
135	                build(snapshotChild, into: container, pool: pool, titles: titles, used: &used)
136	            }
137	        }
138	    }
