142	        let candidates = pool.filter { !used.contains($0.windowId) && isSameApp($0, node) }
143	        // Exact within the session that took the snapshot. Window ids don't survive a restart, so a
144	        // stale id simply fails to resolve and we fall through
145	        if let windowId = node.windowId, let exact = candidates.first(where: { $0.windowId == windowId }) {
146	            return exact
147	        }
148	        if let title = node.windowTitle, !title.isEmpty,
149	           let exact = candidates.first(where: { titles[$0.windowId] == title })
150	        {
151	            return exact
152	        }
153	        return candidates.first
154	    }
