294	func layoutSnapshotUrl(_ name: String) -> ResOrStr<URL> {
295	    if name.isEmpty {
296	        return .failure("Snapshot name must not be empty")
297	    }
298	    // Reject what actually breaks: path traversal, a leading dot hiding the file, a leading dash
299	    // that reads as a flag, and control characters that would mangle 'list' output and menu labels.
300	    // Letters stay unrestricted on purpose, so that Turkish names work
301	    if name.contains("/") || name.contains(":") || name.hasPrefix(".") || name.hasPrefix("-") {
302	        return .failure("Snapshot name \(name.singleQuoted) must not contain '/' or ':', or start with '.' or '-'")
303	    }
304	    if name.rangeOfCharacter(from: .controlCharacters) != nil || name.rangeOfCharacter(from: .newlines) != nil {
305	        return .failure("Snapshot name \(name.singleQuoted) must not contain control characters")
306	    }
307	    return .success(layoutSnapshotsDir().appending(path: name + ".json"))
308	}
